using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.Tilemaps;
using UnityEngine;
using UnityEngine.Tilemaps;

namespace RuralNature32.Editor
{
    // A finite named tile library. Every stamp is a pre-existing 32x32 PNG;
    // no run-length image is stretched or regenerated by this composer.
    public static class NatureModular
    {
        public const string Root=NatureBaker.Root+"/Modular";
        [Serializable] public class Entry { public string id,file,group,label,kind,style;public int mask,row,turn; }
        [Serializable] public class Catalog { public Entry[] palette; }
        public static int Normalize(int mask)
        {
            int[,] triples={{16,1,8},{32,1,2},{64,4,2},{128,4,8}};
            for(int i=0;i<4;i++)if((mask&triples[i,1])==0||(mask&triples[i,2])==0)mask&=~triples[i,0];return mask;
        }
        public static int Mask(HashSet<Vector2Int> ground,Vector2Int p)
        {
            int[,] offsets={{0,-1,1},{1,0,2},{0,1,4},{-1,0,8},{-1,-1,16},{1,-1,32},{1,1,64},{-1,1,128}};int m=0;
            for(int i=0;i<8;i++)if(ground.Contains(p+new Vector2Int(offsets[i,0],offsets[i,1])))m|=offsets[i,2];return Normalize(m);
        }
        public static void RenderGround(HashSet<Vector2Int> ground,int style,Action<string,int,int,bool> stamp)
        {
            string prefix=style==2?"unfinished":"clean";
            foreach(var p in ground)stamp(prefix+"_ground_"+Mask(ground,p).ToString("000"),p.x,p.y,false);
            var directions=new[]{Vector2Int.up,Vector2Int.right,Vector2Int.down,Vector2Int.left};
            // Top-down coordinates; Vector2Int.up is +Y, so invert its Y here.
            var outside=new Dictionary<Vector2Int,int>();
            for(int turn=0;turn<4;turn++)foreach(var p in ground)
            {
                var d=new Vector2Int(directions[turn].x,-directions[turn].y);
                if(ground.Contains(p+d))continue;
                var outer=p+d;if(!outside.ContainsKey(outer))outside[outer]=0;outside[outer]|=1<<turn;
                var inner=p-d;if(ground.Contains(inner)&&Mask(ground,inner)==255)stamp(prefix+"_roots_"+turn,inner.x,inner.y,false);
            }
            foreach(var pair in outside)stamp(prefix+"_detail_"+pair.Value.ToString("00"),pair.Key.x,pair.Key.y,true);
        }
        public static void RenderPlatform(int start,int row,int count,int style,Action<string,int,int,bool> stamp)
        {
            string prefix=style>=5?"colored":style==2?"unfinished":"clean";
            for(int x=0;x<count;x++)for(int layer=0;layer<3;layer++)
            {
                string id;
                if(style==3&&count>=6&&(x<3||x>=count-3))id="painted_"+(x<3?"left_"+x:"right_"+(x-count+3))+"_"+layer;
                else {string col=count==1?"single":x==0?"left":x==count-1?"right":"middle_"+(char)('a'+((x-1)%3));id=prefix+"_platform_"+col+"_"+layer;}
                stamp(id,start+x,row+layer-1,false);
            }
        }
        public static void CreatePalette()
        {
            var catalog=JsonUtility.FromJson<Catalog>(File.ReadAllText(Root+"/tiles.json"));Directory.CreateDirectory(Root+"/Tiles");
            var tiles=new Dictionary<string,Tile>();
            foreach(var item in catalog.palette)
            {
                string file=Root+"/Tiles/"+item.id+".asset";var tile=AssetDatabase.LoadAssetAtPath<Tile>(file);
                if(!tile){tile=ScriptableObject.CreateInstance<Tile>();AssetDatabase.CreateAsset(tile,file);}
                tile.sprite=AssetDatabase.LoadAssetAtPath<Sprite>(Root+"/Textures/"+item.file);
                tile.colliderType=item.kind=="ground"||item.kind=="roots"||(item.kind=="platform"&&item.row==1)?Tile.ColliderType.Grid:Tile.ColliderType.None;
                if(!tile.sprite)throw new Exception("Missing modular sprite "+item.id);EditorUtility.SetDirty(tile);tiles[item.id]=tile;
            }
            string name="RuralNature32_Sketch_Individual",p=NatureBaker.Root+"/Palette/"+name+".prefab";
            if(!File.Exists(p))GridPaletteUtility.CreateNewPalette(NatureBaker.Root+"/Palette",name,GridLayout.CellLayout.Rectangle,GridPalette.CellSizing.Manual,new Vector3(1,1,0),GridLayout.CellSwizzle.XYZ);
            var obj=PrefabUtility.LoadPrefabContents(p);
            try
            {
                var map=obj.GetComponentInChildren<Tilemap>();map.ClearAllTiles();int y=0;
                foreach(var group in catalog.palette.GroupBy(e=>e.group))
                {
                    var items=group.ToArray();int columns=12;
                    if(group.Key=="clean_platform"||group.Key=="unfinished_platform")
                    {
                        string[] roles={"left","middle_a","middle_b","middle_c","right","single"};columns=6;
                        items=items.OrderBy(e=>e.row).ThenBy(e=>Array.FindIndex(roles,role=>e.id.Contains("_platform_"+role+"_"))).ToArray();
                    }
                    for(int i=0;i<items.Length;i++)map.SetTile(new Vector3Int(i%columns,-y-i/columns,0),tiles[items[i].id]);y+=(items.Length+columns-1)/columns+2;
                }
                PrefabUtility.SaveAsPrefabAsset(obj,p);
            }
            finally{PrefabUtility.UnloadPrefabContents(obj);}
            var manual=CreateManualGrid(false);PrefabUtility.SaveAsPrefabAsset(manual,Root+"/RuralSketchManual.prefab");UnityEngine.Object.DestroyImmediate(manual);AssetDatabase.SaveAssets();
        }
        [MenuItem("Tools/Rural Nature 32/Create Manual Sketch Grid")]
        public static void CreateManualMenu(){var obj=CreateManualGrid(true);Undo.RegisterCreatedObjectUndo(obj,"Create manual sketch grid");Selection.activeGameObject=obj.transform.GetChild(0).gameObject;OpenPalette();GridPaintingState.scenePaintTarget=Selection.activeGameObject;}
        static GameObject CreateManualGrid(bool select)
        {
            var obj=new GameObject("Manual 32px sketch tiles",typeof(Grid));obj.GetComponent<Grid>().cellSize=new Vector3(1,1,0);
            foreach(bool platform in new[]{false,true})
            {
                var map=NatureBaker.Layer(obj.transform,platform?"Platforms - individual tiles":"Ground - individual tiles",true,platform);
                var renderer=map.GetComponent<TilemapRenderer>();renderer.enabled=true;renderer.sharedMaterial=NatureDemo.Unlit;
            }
            return obj;
        }
        [MenuItem("Tools/Rural Nature 32/Open Named Sketch Tile Palette")]
        public static void OpenPalette()
        {
            CreatePalette();EditorApplication.ExecuteMenuItem("Window/2D/Tile Palette");
            GridPaintingState.palette=AssetDatabase.LoadAssetAtPath<GameObject>(NatureBaker.Root+"/Palette/RuralNature32_Sketch_Individual.prefab");
        }
    }
}
